        parts = schema.get('anyOf') or schema.get('oneOf')
        result = ' | '.join(ts_type(part, in_union=True) for part in parts)
    elif 'allOf' in schema:
        result = ' & '.join(ts_type(part, in_intersection=True) for part in schema['allOf'])
    else:
        kind = schema.get('type')
        if kind == 'array':
            result = '(' + ts_type(schema['items']) + ')[]'
        elif kind == 'object' or 'properties' in schema:
